export function addTask(tasks, title) {
  if (typeof title !== 'string' || (title = title.trim()).length === 0) {
    throw new Error('Title must be a non-empty string.');
  }
  const nextId = tasks.reduce((maxId, task) => Math.max(maxId, task.id), 0) + 1;
  return [...tasks, { id: nextId, title, done: false }];
}

export function completeTask(tasks, id) {
  return tasks.map(task => task.id === id ? { ...task, done: true } : task);
}

