import assert from 'node:assert/strict';
import { addTask, completeTask } from '../src/tasks.js';

// Test adding a valid task
let tasks = addTask([], 'Ship safely');
assert.equal(tasks.length, 1);
assert.equal(tasks[0].id, 1);
assert.equal(tasks[0].title, 'Ship safely');
assert.equal(tasks[0].done, false);

// Test completing a task
assert.equal(completeTask(tasks, 1)[0].done, true);

// Test adding a task with leading/trailing spaces
let trimmedTask = addTask([], '  Clean up  ');
assert.equal(trimmedTask[0].title, 'Clean up');

// Test adding an empty task title
assert.throws(() => addTask([], ''), /Invalid task title/);

// Test adding a non-string task title
assert.throws(() => addTask([], 123), /Invalid task title/);

// Test adding multiple tasks and ensuring unique IDs
let task1 = addTask([], 'Task 1')[0];
let task2 = addTask([task1], 'Task 2')[0];
assert.notEqual(task1.id, task2.id);

// Test adding tasks after removing one
let task3 = addTask([task1, task2], 'Task 3')[0];
task2 = completeTask([task1, task2, task3], task2.id).find(t => t.id === task2.id);
task2 = addTask([task1, task2, task3], 'Re-added Task 2')[0];
assert.notEqual(task2.id, task3.id);
